//! Frozen observations of the original executable, not expectations generated by this implementation.
use serde_json::Value;
use xcasl2_core::{assemble, Machine, Session, Status};

fn number(value: &Value, default: u16) -> u16 {
    value.as_u64().map_or(default, |n| n as u16)
}
fn cases(name: &str) -> Vec<Value> {
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../analysis/results")
        .join(name);
    serde_json::from_slice(&std::fs::read(path).unwrap()).unwrap()
}

#[test]
fn original_cpu_execution_stage_1420_cases() {
    let data = cases("cpu_cases.json");
    assert_eq!(data.len(), 1420);
    let mut failures = Vec::new();
    for case in data {
        let id = case["id"].as_str().unwrap();
        let input = &case["input"];
        let expected = &case["final"];
        let mut machine = Machine::new(0, 0, number(&input["sp"], 0x200));
        machine.cpu.fr = number(&input["fr"], 0);
        machine.cpu.depth = number(&input["depth"], 0) as u32;
        if let Some(registers) = input["gr"].as_object() {
            for (register, value) in registers {
                machine.cpu.gr[register.parse::<usize>().unwrap()] = number(value, 0);
            }
        }
        let effective = number(&input["effective"], 0x100);
        machine.write(effective, number(&input["operand"], 0));
        let op = u8::from_str_radix(case["opcode"].as_str().unwrap(), 16).unwrap();
        machine.execute_decoded(
            op,
            number(&input["r"], 1) as usize,
            number(&input["x"], 2) as usize,
            effective,
        );
        let actual = serde_json::to_value(&machine.cpu).unwrap();
        for key in ["gr", "fr", "sp", "pr", "depth"] {
            if actual[key] != expected[key] {
                failures.push(format!("{id} {key}: {} != {}", actual[key], expected[key]));
            }
        }
        for (address, word) in case["memory"].as_object().unwrap() {
            let address = u16::from_str_radix(address.trim_start_matches("0x"), 16).unwrap();
            if machine.read(address) != number(word, 0) {
                failures.push(format!("{id} memory #{address:04X}"));
            }
        }
        if matches!(op, 0x90 | 0xff) {
            assert_eq!(machine.status, Status::Fault, "{id}");
        }
    }
    assert!(
        failures.is_empty(),
        "{} differences:\n{}",
        failures.len(),
        failures
            .iter()
            .take(30)
            .cloned()
            .collect::<Vec<_>>()
            .join("\n")
    );
}

#[test]
fn original_build_success_failure_and_linked_memory() {
    let mut checked = 0;
    for case in cases("build_cases.json") {
        let id = case["id"].as_str().unwrap();
        // Explicitly deferred or intentionally safer behavior; never silently count these as matching.
        if matches!(id, "literal_address" | "duplicate_global") {
            continue;
        }
        let source = case["source"].as_str().unwrap();
        let result = assemble(source, 0x20);
        let linked = number(&case["end"], 0) != 0;
        assert_eq!(result.is_ok(), linked, "{id}: {result:?}");
        if let Ok(image) = result {
            assert_eq!(image.entry, number(&case["entry"], 0), "{id} entry");
            assert_eq!(image.program_end + 128, number(&case["end"], 0), "{id} end");
            let machine = image.load(0xffff);
            for (address, word) in case["memory"]
                .as_array()
                .unwrap()
                .iter()
                .enumerate()
                .take(3000)
            {
                assert_eq!(
                    machine.read(address as u16),
                    number(word, 0),
                    "{id} memory #{address:04X}"
                );
            }
        }
        checked += 1;
    }
    assert_eq!(checked, 94);
}

#[test]
fn physical_memory_and_wrapping_stack_are_safe() {
    let mut machine = Machine::new(0, 0, 0);
    machine.write(2999, 123);
    machine.write(3000, 456);
    machine.write(65535, 789);
    assert_eq!(machine.read(2999), 123);
    assert_eq!(machine.read(3000), 0xffff);
    assert_eq!(machine.read(65535), 0xffff);
    machine.execute_decoded(0x70, 0, 0, 0x1234);
    assert_eq!(machine.cpu.sp, 65535);
    machine.execute_decoded(0x71, 1, 0, 0);
    assert_eq!(machine.cpu.sp, 0);
    assert_eq!(machine.cpu.gr[1], 0xffff);
}

#[test]
fn echo_cp932_and_rewind_requires_new_input() {
    let image = assemble(
        "MAIN START\n IN BUF,LEN\n OUT BUF,LEN\n RET\nBUF DS 128\nLEN DS 1\n END\n",
        32,
    )
    .unwrap();
    let mut session = Session::new(image, 0xffff);
    session.run_batch(100);
    assert_eq!(session.machine.status, Status::WaitingInput);
    session.input(Some("あｱ")).unwrap();
    session.run_batch(100);
    assert_eq!(session.machine.status, Status::Halted);
    assert_eq!(session.machine.output(), ["あｱ"]);
    session.back();
    assert_eq!(session.machine.status, Status::WaitingInput);
    assert!(session.snapshot().replay_target.is_some());
    session.input(Some("NEW")).unwrap();
    assert_eq!(session.machine.output(), ["NEW"]);
    assert_eq!(session.machine.status, Status::Ready);
    session.step();
    assert_eq!(session.machine.status, Status::Halted);
}

#[test]
fn empty_input_and_eof_do_not_erase_buffer() {
    for (text, length) in [(Some(""), 0), (None, 0xffff)] {
        let mut machine = Machine::new(0xcccc, 0, 0x200);
        machine.cpu.gr[1] = 0x100;
        machine.cpu.gr[2] = 0x90;
        machine.execute_decoded(0xf0, 0, 0, 1);
        machine.supply_input(text).unwrap();
        assert_eq!(machine.read(0x90), length);
        assert_eq!(machine.read(0x100), 0xcccc);
    }
}

#[test]
fn original_line_boundary_54_cases() {
    let data = cases("followup_boundaries.json");
    assert_eq!(data.len(), 54);
    for case in data {
        let result = assemble(case["source"].as_str().unwrap(), 32);
        assert_eq!(
            result.is_ok(),
            number(&case["end"], 0) != 0,
            "{}: {result:?}",
            case["id"]
        );
        if let Ok(image) = result {
            assert_eq!(image.entry, number(&case["entry"], 0));
            assert_eq!(image.program_end + 128, number(&case["end"], 0));
        }
    }
}

fn unhex(text: &str) -> Vec<u8> {
    (0..text.len())
        .step_by(2)
        .map(|offset| u8::from_str_radix(&text[offset..offset + 2], 16).unwrap())
        .collect()
}

#[test]
fn original_keyboard_and_display_10_cases() {
    let data = cases("io_cases.json");
    assert_eq!(data.len(), 10);
    for case in data {
        let id = case["id"].as_str().unwrap();
        let mut machine = Machine::new(0, 0, 0);
        machine.cpu.gr[1] = 0x100;
        machine.cpu.gr[2] = 0x90;
        machine.cpu.fr = 7;
        if id.starts_with("IN-") {
            for address in 0x100..0x200 {
                machine.write(address, 0xcccc);
            }
            machine.execute_decoded(0xf0, 0, 0, 1);
            let text = xcasl2_core::decode_cp932(&unhex(case["input_hex"].as_str().unwrap()));
            machine
                .supply_input(if case["eof"].as_bool().unwrap() {
                    None
                } else {
                    Some(&text)
                })
                .unwrap();
            assert_eq!(machine.read(0x90), number(&case["length"], 0), "{id}");
            for (i, word) in case["buffer"].as_array().unwrap().iter().enumerate() {
                assert_eq!(machine.read(0x100 + i as u16), number(word, 0), "{id}");
            }
        } else {
            let words = case["words"].as_array().unwrap();
            machine.write(0x90, words.len() as u16);
            for (i, word) in words.iter().enumerate() {
                machine.write(0x100 + i as u16, number(word, 0));
            }
            machine.execute_decoded(0xf0, 0, 0, 2);
            let output = machine.output();
            let rows = case["display_rows_hex"].as_array().unwrap();
            for (i, row) in rows.iter().enumerate() {
                let expected = xcasl2_core::decode_cp932(&unhex(row.as_str().unwrap()));
                assert_eq!(
                    output.get(i).map_or("", String::as_str),
                    expected,
                    "{id} row {i}"
                );
            }
        }
        assert_eq!(machine.cpu.gr, [0, 0x100, 0x90, 0, 0, 0, 0, 0], "{id}");
        assert_eq!(machine.cpu.fr, 7, "{id}");
    }
}

#[test]
fn macro_step_and_subroutine_return_are_machine_instructions() {
    let image = assemble("MAIN START\n CALL SUB\n OUT BUF,LEN\n RET\nBUF DC 'X'\nLEN DC 1\n END\nSUB START\n LAD GR0,7\n RET\n END\n", 32).unwrap();
    let initial_sp = image.program_end + 129;
    let mut session = Session::new(image, 0xffff);
    session.step();
    assert_eq!(session.machine.cpu.depth, 1);
    session.step();
    session.step();
    assert_eq!(session.machine.cpu.pr, 34);
    session.step();
    assert_eq!(session.machine.cpu.pr, 36);
    assert_eq!(session.machine.cpu.sp, initial_sp - 1);
    assert_eq!(session.machine.output(), [""]);
    session.run_batch(100);
    assert_eq!(session.machine.output(), ["X"]);
    assert_eq!(session.machine.cpu.sp, initial_sp);
    assert_eq!(session.machine.cpu.gr[0], 7);
}

#[test]
fn long_rewind_is_bounded_and_stops_at_its_destination() {
    let image = assemble("MAIN START\n ADDL GR1,=1\n JUMP MAIN\n END\n", 32).unwrap();
    let mut session = Session::new(image, 0xffff);
    session.run_batch(1000);
    session.run_batch(1000);
    session.back();
    assert_eq!(session.steps, 1000);
    assert_eq!(session.snapshot().replay_target, Some(1999));
    session.run_batch(1000);
    assert_eq!(session.steps, 1999);
    assert_eq!(session.snapshot().replay_target, None);
    assert_eq!(session.machine.cpu.gr[1], 999);
}
